#!/bin/bash
#
# Copies the generated QR images (qr/images) into each implementation's asset
# directory, and writes the lists each toolchain needs to bundle them.
#
#   ./qr/scripts/sync-images.sh
#
# The images are generated by bench/scripts/make-qr-images.swift and committed,
# so this only has to run when the image set changes. Each app keeps its own
# copy because Flutter cannot reference assets outside its package and Metro
# cannot require files outside the project without extra configuration —
# a copy is less machinery than either workaround.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
IMAGES="$ROOT/qr/images"

count="$(find "$IMAGES" -name 'qr-*.png' | wc -l | tr -d ' ')"
if [[ "$count" -eq 0 ]]; then
  echo "no images in $IMAGES; run bench/scripts/make-qr-images.swift first" >&2
  exit 1
fi

copy_into() {
  local target="$1"
  rm -rf "$target"
  mkdir -p "$target"
  cp "$IMAGES"/qr-*.png "$target/"
}

# iOS: a folder reference in the app bundle, so the files keep their names.
copy_into "$ROOT/qr/native/ios/QrApp/qr"
# Android: src/main/assets, read back with AssetManager.
copy_into "$ROOT/qr/native/android/app/src/main/assets/qr"
# Flutter: declared in pubspec.yaml, read back with rootBundle.
copy_into "$ROOT/qr/flutter/app/assets/qr"
# React Native: plugins/withQrImages.js copies these into the native projects
# during `expo prebuild`, because expo-asset cannot file them as plain files.
copy_into "$ROOT/qr/expo/app/assets/qr"

# Flutter declares the asset directory rather than each file, so only the count
# is written out; the app builds the names from it.
dart_list="$ROOT/qr/flutter/app/lib/src/qr_assets.dart"
mkdir -p "$(dirname "$dart_list")"
{
  echo "// Generated by qr/scripts/sync-images.sh."
  echo "const qrImageCount = $count;"
} > "$dart_list"

echo "synced $count images into the four apps"
